from typing import Annotated

from fastapi import APIRouter, HTTPException, Path, Response

from ...api.dependencies import Repository
from .schemas import Priority, Todo, TodoCreate, TodoUpdate

router = APIRouter(prefix="/api/todos", tags=["todos"])
TodoId = Annotated[int, Path(gt=0)]


@router.get("", response_model=list[Todo])
def list_todos(repo: Repository, priority: Priority | None = None):
    todos = repo.list()
    if priority is None:
        return todos
    return [todo for todo in todos if todo.priority == priority]


@router.post("", response_model=Todo, status_code=201)
def create_todo(payload: TodoCreate, repo: Repository):
    return repo.create(payload)


@router.get("/{todo_id}", response_model=Todo)
def get_todo(todo_id: TodoId, repo: Repository):
    todo = repo.get(todo_id)
    if todo is None:
        raise HTTPException(404, "Task not found.")
    return todo


@router.patch("/{todo_id}", response_model=Todo)
def update_todo(todo_id: TodoId, payload: TodoUpdate, repo: Repository):
    todo = repo.update(todo_id, payload)
    if todo is None:
        raise HTTPException(404, "Task not found.")
    return todo


@router.delete("/{todo_id}", status_code=204)
def delete_todo(todo_id: TodoId, repo: Repository):
    if not repo.delete(todo_id):
        raise HTTPException(404, "Task not found.")
    return Response(status_code=204)

import { useState } from 'react'
import { Alert, Button } from '../../design-system'
import { SuccessNotice } from '../../components/SuccessNotice'
import { useNotice } from '../../hooks/useNotice'
import { DeleteTodoDialog } from './components/DeleteTodoDialog'
import { TodoEditor } from './components/TodoEditor'
import { TodoFilters } from './components/TodoFilters'
import { TodoList } from './components/TodoList'
import { TodosHeader } from './components/TodosHeader'
import { useTodoFilters } from './hooks/useTodoFilters'
import { useTodosBusy } from './hooks/useTodosBusy'
import { useTodosQuery } from './hooks/useTodosQuery'
import { useUpdateTodoMutation } from './hooks/useUpdateTodoMutation'
import type { Priority, Todo } from './types'

export function TodosPage() {
  const [priority, setPriority] = useState<Priority | ''>('')
  const todosQuery = useTodosQuery(priority || undefined)
  const todos = todosQuery.data ?? []
  const filters = useTodoFilters(todos)
  const toggleTodo = useUpdateTodoMutation()
  const busy = useTodosBusy()
  const { message, notify } = useNotice()
  const [editor, setEditor] = useState<Todo | 'new' | null>(null)
  const [deleting, setDeleting] = useState<Todo | null>(null)
  const error = toggleTodo.error ?? todosQuery.error

  async function toggle(todo: Todo) {
    if (busy) return
    try {
      const saved = await toggleTodo.mutateAsync({
        id: todo.id,
        input: { completed: !todo.completed },
      })
      notify(
        saved.completed
          ? 'Another task complete. Well done!'
          : 'Task marked as active.',
      )
    } catch {
      // Display the mutation error in the page alert.
    }
  }
  async function retry() {
    toggleTodo.reset()
    await todosQuery.refetch()
  }

  return (
    <>
      <main id="main" className="page-layout">
        <TodosHeader
          disabled={todosQuery.isPending || busy}
          onCreate={() => setEditor('new')}
        />
        <TodoFilters
          filter={filters.filter}
          search={filters.search}
          sort={filters.sort}
          priority={priority}
          onFilterChange={filters.setFilter}
          onSearchChange={filters.setSearch}
          onSortChange={filters.setSort}
          onPriorityChange={setPriority}
        />
        {error && (
          <Alert variant="warning">
            {error.message}
            <Button
              variant="secondary"
              disabled={todosQuery.isFetching || busy}
              onClick={() => void retry()}
            >
              Try again
            </Button>
          </Alert>
        )}
        <TodoList
          todos={filters.visible}
          hasTodos={
            todos.length > 0 || (Boolean(priority) && !todosQuery.isError)
          }
          loading={todosQuery.isPending}
          failed={todosQuery.isError}
          busy={busy}
          onCreate={() => setEditor('new')}
          onToggle={(todo) => void toggle(todo)}
          onEdit={setEditor}
          onDelete={setDeleting}
        />
      </main>
      <SuccessNotice message={message} />
      {editor && (
        <TodoEditor
          todo={editor}
          busy={busy}
          onClose={() => setEditor(null)}
          onSaved={(notice) => {
            setEditor(null)
            notify(notice)
          }}
        />
      )}
      {deleting && (
        <DeleteTodoDialog
          todo={deleting}
          busy={busy}
          onClose={() => setDeleting(null)}
          onDeleted={() => {
            setDeleting(null)
            notify('Task deleted.')
          }}
        />
      )}
    </>
  )
}

import { request } from '../../../lib/http'
import type { Priority, Todo, TodoInput } from '../types'

export const todosApi = {
  list: (signal?: AbortSignal, priority?: Priority) =>
    request<Todo[]>(priority ? `/todos?priority=${priority}` : '/todos', {
      signal,
    }),
  create: (input: TodoInput) => {
    // A form initialized with a Todo must never send read-only fields.
    const { title, description, priority, due_date, completed } = input
    return request<Todo>('/todos', {
      method: 'POST',
      body: JSON.stringify({
        title,
        description,
        priority,
        due_date,
        completed,
      }),
    })
  },
  update: (id: number, input: Partial<TodoInput>) => {
    const { title, description, priority, due_date, completed } = input
    return request<Todo>(`/todos/${id}`, {
      method: 'PATCH',
      body: JSON.stringify({
        title,
        description,
        priority,
        due_date,
        completed,
      }),
    })
  },
  remove: (id: number) => request<void>(`/todos/${id}`, { method: 'DELETE' }),
}

import { Plus } from 'lucide-react'
import { Button, Card, Heading, Text } from '../../../design-system'

export function TodoEmptyState({
  hasTodos,
  disabled,
  onCreate,
}: {
  hasTodos: boolean
  disabled: boolean
  onCreate: () => void
}) {
  return (
    <Card>
      <Heading level={3}>
        {hasTodos ? 'No matching tasks' : 'Add your first task'}
      </Heading>
      <Text muted>
        {hasTodos
          ? 'Change the filters or search to find your tasks.'
          : 'Write down what you need to do and get started.'}
      </Text>
      {!hasTodos && (
        <div>
          <Button variant="secondary" disabled={disabled} onClick={onCreate}>
            <Plus size={16} aria-hidden="true" />
            Add your first task
          </Button>
        </div>
      )}
    </Card>
  )
}

import { Input, Select } from '../../../design-system'
import type { Filter, Priority, Sort } from '../types'

interface TodoFiltersProps {
  filter: Filter
  search: string
  sort: Sort
  priority?: Priority | ''
  onFilterChange: (filter: Filter) => void
  onSearchChange: (search: string) => void
  onSortChange: (sort: Sort) => void
  onPriorityChange?: (priority: Priority | '') => void
}

export function TodoFilters({
  filter,
  search,
  sort,
  priority = '',
  onFilterChange,
  onSearchChange,
  onSortChange,
  onPriorityChange,
}: TodoFiltersProps) {
  return (
    <section className="filters-layout" aria-label="Task filters">
      <Input
        label="Search tasks"
        placeholder="Type to search…"
        value={search}
        onChange={(event) => onSearchChange(event.target.value)}
      />
      <Select
        label="Status"
        value={filter}
        onChange={(event) => onFilterChange(event.target.value as Filter)}
        options={[
          { value: 'all', label: 'All statuses' },
          { value: 'active', label: 'To do' },
          { value: 'completed', label: 'Completed' },
        ]}
      />
      <Select
        label="Sort by"
        value={sort}
        onChange={(event) => onSortChange(event.target.value as Sort)}
        options={[
          { value: 'newest', label: 'Newest' },
          { value: 'priority', label: 'Priority' },
          { value: 'due', label: 'Due date' },
        ]}
      />
      <Select
        label="Priority"
        value={priority}
        onChange={(event) =>
          onPriorityChange?.(event.target.value as Priority | '')
        }
        options={[
          { value: '', label: 'All priorities' },
          { value: 'high', label: 'High' },
          { value: 'medium', label: 'Medium' },
          { value: 'low', label: 'Low' },
        ]}
      />
    </section>
  )
}

import { useMutation, useQueryClient } from '@tanstack/react-query'
import { todoKeys } from '../api/queryKeys'
import { todosApi } from '../api/todos'
import type { Todo, TodoInput } from '../types'

export function useCreateTodoMutation() {
  const queryClient = useQueryClient()
  return useMutation({
    mutationKey: todoKeys.create,
    mutationFn: (input: TodoInput) => todosApi.create(input),
    onSuccess: async (saved) => {
      // Stop an older refetch from overwriting the confirmed server response.
      await queryClient.cancelQueries({ queryKey: todoKeys.list })
      queryClient.setQueryData<Todo[]>(todoKeys.list, (current = []) => [
        saved,
        ...current.filter((todo) => todo.id !== saved.id),
      ])
      await queryClient.invalidateQueries({ queryKey: todoKeys.priorityLists })
    },
  })
}

import { useMutation, useQueryClient } from '@tanstack/react-query'
import { todoKeys } from '../api/queryKeys'
import { todosApi } from '../api/todos'
import type { Todo } from '../types'

export function useDeleteTodoMutation() {
  const queryClient = useQueryClient()
  return useMutation({
    mutationKey: todoKeys.delete,
    mutationFn: (id: number) => todosApi.remove(id),
    onSuccess: async (_, id) => {
      await queryClient.cancelQueries({ queryKey: todoKeys.list })
      queryClient.setQueryData<Todo[]>(todoKeys.list, (current) =>
        current?.filter((todo) => todo.id !== id),
      )
      await queryClient.invalidateQueries({ queryKey: todoKeys.priorityLists })
    },
  })
}

import { useQuery } from '@tanstack/react-query'
import { todoKeys } from '../api/queryKeys'
import { todosApi } from '../api/todos'
import type { Priority } from '../types'

export function useTodosQuery(priority?: Priority) {
  return useQuery({
    queryKey: priority ? [...todoKeys.priorityLists, priority] : todoKeys.list,
    queryFn: ({ signal }) => todosApi.list(signal, priority),
  })
}

import { useMutation, useQueryClient } from '@tanstack/react-query'
import { todoKeys } from '../api/queryKeys'
import { todosApi } from '../api/todos'
import type { Todo, TodoInput } from '../types'

export function useUpdateTodoMutation() {
  const queryClient = useQueryClient()
  return useMutation({
    mutationKey: todoKeys.update,
    mutationFn: ({ id, input }: { id: number; input: Partial<TodoInput> }) =>
      todosApi.update(id, input),
    onSuccess: async (saved) => {
      await queryClient.cancelQueries({ queryKey: todoKeys.list })
      queryClient.setQueryData<Todo[]>(todoKeys.list, (current) =>
        current?.map((todo) => (todo.id === saved.id ? saved : todo)),
      )
      await queryClient.invalidateQueries({ queryKey: todoKeys.priorityLists })
    },
  })
}
